       UPDATE SAWON_MST
       SET POSITION = #{POSITION}
       	,NAME = #{NAME}
       	,TELNO = #{TELNO}
       	,HANDNO = #{HANDNO}
       	,IPDATE = REPLACE(#{IPDATE},'-','')
       	,REMK = #{REMK}
       	,MEMODATE = DATEFORMAT(GETDATE(),'YYYYMMDD')
       WHERE CODE = #{CODE}
